style.css:
@-moz-document domain("pinterest.com") {
/* 1. IMPORT & FORCE FONT */
    @font-face {
        font-family: 'Dunkin';
        src: local('Dunkin'), local('Dunkin Sans');
    }

    /* 2. THE STRICT NEAPOLITAN PALETTE */
    :root {
        /* Vanilla / Custard */
        --bg: #FDF5E6 !important; 
        /* Strawberry Pink */
        --pink: #FFB7C5 !important;
        /* Chocolate Brown */
        --choc: #5D4037 !important;
        
        /* HIJACK PINTEREST INTERNAL VARS */
        --g-colorRed00: var(--pink) !important;
        --g-colorRed100: var(--pink) !important;
        --g-colorGray0: var(--bg) !important;
        --g-colorGray100: #F5E6CC !important;
        --g-colorGray200: var(--choc) !important;
        --g-colorGray300: var(--choc) !important;
        --g-colorGray400: var(--choc) !important;
        --g-bg-color: var(--bg) !important;
        --color-background-container-primary: var(--bg) !important;
        --color-background-canvas: var(--bg) !important;
        --color-background-main: var(--bg) !important;
    }

    /* 3. APPLY FONT & COLORS EVERYWHERE */
    * {
        font-family: 'Dunkin', 'Quicksand', sans-serif !important;
        color: var(--choc) !important;
        border-color: var(--choc) !important;
    }

    /* 4. KILL THE WHITE (Aggressive Override) */
    html, body, #__PWS_ROOT__, [role="main"], [data-test-id="full-grid-container"],
    [data-test-id="header-background"], #HeaderContent, 
    div[class*="FullPageModal"], div[role="dialog"] {
        background-color: var(--bg) !important;
    }

    /* 5. STRAWBERRY BUTTONS & ACCENTS */
    button, [role="button"], [data-test-id="save-button"], 
    div[style*="background-color: rgb(230, 0, 35)"] {
        background-color: var(--pink) !important;
        border: 2px solid var(--choc) !important;
        border-radius: 12px !important; /* Slightly more "Dunkin" style square-round */
    }

    /* 6. PIN CARDS - THE TREATS */
    [data-test-id="pin-visual-wrapper"] {
        background-color: var(--bg) !important;
        border: 4px solid var(--choc) !important;
        border-radius: 20px !important;
    }

    img {
        border-bottom: 2px solid var(--choc) !important;
    }

    /* 7. THE MASCOT (Bottom Right) */
    body::after {
        content: "";
        position: fixed;
        bottom: 15px;
        right: 15px;
        width: 100px;
        height: 100px;
        background-image: url('https://i.imgur.com/vH7j3iO.png'); 
        background-size: contain;
        background-repeat: no-repeat;
        z-index: 9999;
        pointer-events: none;
        filter: drop-shadow(2px 2px 0px var(--choc));
    }

    /* 8. SEARCH BAR */
    [data-test-id="search-box-input"] {
        background-color: #F5E6CC !important;
        border: 3px solid var(--choc) !important;
        font-size: 1.1em !important;
    }

    /* 9. ICONS */
    svg {
        fill: var(--choc) !important;
    }

    /* 10. SCROLLBAR */
    ::-webkit-scrollbar { width: 10px; }
    ::-webkit-scrollbar-track { background: var(--choc); }
    ::-webkit-scrollbar-thumb { 
        background: var(--pink); 
        border: 2px solid var(--choc);
    }
}
